import os, re

# Load all grids from session history
def load_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}
    try:
        sessions_file = os.path.join(d, '..', 'sessions', os.path.basename(d) + '.jsonl')
        if os.path.exists(sessions_file):
            f = open(sessions_file)
            content = f.read()
            f.close()

            # Parse demo inputs/outputs and test input
            grids = {}

            # Pattern for demo/test descriptions
            desc_pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
            for m in re.finditer(desc_pattern, content):
                key, h, w = m[1], int(m[2]), int(m[3])

                # Extract rows until next section or end
                rest = content[m.end():]
                newlines = 0
                max_rows = h

                # Count newlines to find the grid block
                while newlines < max_rows:
                    if rest.startswith('\n'):
                        rest = rest[1:]
                        newlines += 1
                    elif rest.startswith('Wrong attempts') or rest.startswith('Demo requests') or 'Task id:' in rest or rest.strip() == '':
                        break
                    else:
                        if any(c.isdigit() for c in rest):
                            row_parts = rest.split()[:w]
                            if row_parts:
                                grids[key] = [[int(x) for x in row_parts]]
                        rest = ''
                        break
                    elif rest.startswith('0 ') and len(rest) > 2:
                        row_start = rest.find(' ')
                        row_end = min(row_start + 100, len(rest))
                        row_str = rest[row_start+1:row_end].strip()
                        if row_str and row_str.replace('.','',len('.')):
                            pass
                break

            return grids
    except:
        return {}

print("Loading from:", os.environ.get('RLM_SESSION_DIR'))
grids = load_grids()
print("Found grids:", list(grids.keys()))

